'use client';

import { useState, useRef } from 'react';
import { trpc } from '@/lib/trpc';
import { useToast } from '@/components/ui/toast';
import { Camera, Save, Lock } from 'lucide-react';
import Link from 'next/link';

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

export default function SettingsPage() {
  const { toast } = useToast();
  const utils = trpc.useUtils();
  const { data: profile, isLoading } = trpc.user.getProfile.useQuery();
  const { data: storage } = trpc.user.getStorageDetails.useQuery();

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [loaded, setLoaded] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const updateProfile = trpc.user.updateProfile.useMutation({
    onSuccess: () => {
      toast('Profile updated', 'success');
      utils.user.getProfile.invalidate();
    },
    onError: (err) => toast(err.message, 'error'),
  });

  const uploadAvatar = trpc.user.uploadAvatar.useMutation({
    onSuccess: () => {
      toast('Avatar updated', 'success');
      utils.user.getProfile.invalidate();
    },
    onError: (err) => toast(err.message, 'error'),
  });

  if (isLoading) return <div className="p-4">Loading...</div>;
  if (!profile) return null;

  if (!loaded && profile) {
    setName(profile.name);
    setEmail(profile.email);
    setLoaded(true);
  }

  const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // For now, create a data URL as placeholder
    // In production, upload to S3
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        uploadAvatar.mutate({ avatarUrl: reader.result });
      }
    };
    reader.readAsDataURL(file);
  };

  const usedPercent = storage ? Math.min((storage.used / storage.capacityBytes) * 100, 100) : 0;

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold text-gray-900">Account Settings</h1>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        {/* Profile Card */}
        <div className="rounded-lg border border-gray-200 bg-white p-6 lg:col-span-2">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="text-lg font-semibold">Profile</h2>
            <Link
              href="/settings/password"
              className="flex items-center gap-1 text-sm text-blue-600 hover:text-blue-800"
            >
              <Lock className="h-4 w-4" />
              Change Password
            </Link>
          </div>

          {/* Avatar */}
          <div className="mb-6 flex items-center gap-4">
            <div className="relative">
              <div className="h-20 w-20 overflow-hidden rounded-full bg-gray-200">
                {profile.avatar ? (
                  <img src={profile.avatar} alt={profile.name} className="h-full w-full object-cover" />
                ) : (
                  <div className="flex h-full w-full items-center justify-center text-2xl font-bold text-gray-500">
                    {profile.name?.charAt(0).toUpperCase() ?? 'U'}
                  </div>
                )}
              </div>
              <button
                onClick={() => fileInputRef.current?.click()}
                className="absolute bottom-0 right-0 rounded-full bg-blue-600 p-1.5 text-white hover:bg-blue-700"
              >
                <Camera className="h-3.5 w-3.5" />
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleAvatarUpload}
                className="hidden"
              />
            </div>
            <div>
              <p className="font-medium text-gray-900">{profile.name}</p>
              <p className="text-sm text-gray-500">{profile.email}</p>
            </div>
          </div>

          {/* Form */}
          <div className="space-y-4">
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">Name</label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
            </div>

            <button
              onClick={() => updateProfile.mutate({ name, email })}
              disabled={updateProfile.isPending || (name === profile.name && email === profile.email)}
              className="flex items-center gap-1 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
            >
              <Save className="h-4 w-4" />
              {updateProfile.isPending ? 'Saving...' : 'Save Changes'}
            </button>
          </div>
        </div>

        {/* Storage Card */}
        <div className="rounded-lg border border-gray-200 bg-white p-6">
          <h2 className="mb-4 text-lg font-semibold">Storage</h2>

          {storage && (
            <div className="space-y-4">
              <div>
                <div className="mb-1 flex justify-between text-sm">
                  <span className="text-gray-600">{formatBytes(storage.used)} used</span>
                  <span className="text-gray-600">{storage.capacity} GB</span>
                </div>
                <div className="h-2.5 w-full rounded-full bg-gray-200">
                  <div
                    className={`h-2.5 rounded-full ${
                      usedPercent > 90 ? 'bg-red-500' : usedPercent > 70 ? 'bg-yellow-500' : 'bg-green-500'
                    }`}
                    style={{ width: `${usedPercent}%` }}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <h3 className="text-sm font-medium text-gray-700">By Type</h3>
                <div className="space-y-1">
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Images</span>
                    <span className="text-gray-700">{formatBytes(storage.breakdown.images ?? 0)}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Documents</span>
                    <span className="text-gray-700">{formatBytes(storage.breakdown.documents ?? 0)}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Videos</span>
                    <span className="text-gray-700">{formatBytes(storage.breakdown.videos ?? 0)}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-500">Other</span>
                    <span className="text-gray-700">{formatBytes(storage.breakdown.other ?? 0)}</span>
                  </div>
                </div>
              </div>

              <p className="text-xs text-gray-500">{storage.fileCount} files total</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// src/app/api/avatars/[...path]/route.ts
// Avatar serving API ÔÇö resolves S3 avatar keys, serves presigned redirects

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/server/db';
import { auth } from '@/server/auth';
import { getPresignedDownloadUrl } from '@/lib/s3';
import { checkRateLimit, RATE_LIMITS } from '@/lib/rate-limit';
import { getClientIp } from '@/lib/api-security';

const DEFAULT_AVATAR_URL =
  process.env.DEFAULT_AVATAR_URL ?? '/avatars/default.png';

function sanitizeSegment(seg: string): string | null {
  // reject path traversal, null bytes, anything non-filename
  if (
    seg.includes('..') ||
    seg.includes('\0') ||
    seg.includes('/') ||
    seg.includes('\\')
  ) {
    return null;
  }
  // only allow alphanumeric, hyphens, underscores, dots
  if (!/^[a-zA-Z0-9._\-]+$/.test(seg)) {
    return null;
  }
  return seg;
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> },
) {
  // ÔöÇÔöÇ Rate limit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const ip = getClientIp(request);
  const rl = checkRateLimit(`avatar:${ip}`, RATE_LIMITS.api);
  if (!rl.allowed) {
    return NextResponse.json(
      { error: 'Too many requests' },
      {
        status: 429,
        headers: { 'Retry-After': String(Math.ceil((rl.resetAt - Date.now()) / 1000)) },
      },
    );
  }

  const { path } = await params;

  if (!path || path.length === 0) {
    return NextResponse.json({ error: 'Path required' }, { status: 400 });
  }

  // ÔöÇÔöÇ Validate & sanitize all segments ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const segments: string[] = [];
  for (const seg of path) {
    const clean = sanitizeSegment(seg);
    if (clean === null) {
      return NextResponse.json({ error: 'Invalid path' }, { status: 400 });
    }
    segments.push(clean);
  }

  // ÔöÇÔöÇ Parse path formats ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  // Two supported formats:
  //   /api/avatars/{userId}/{filename}   ÔÇö user-specific avatar
  //   /api/avatars/{filename}            ÔÇö flat lookup (default avatar)
  let userId: number | null = null;
  let filename: string;

  if (segments.length >= 2) {
    // {userId}/{filename}
    const parsedId = Number(segments[0]);
    if (!Number.isFinite(parsedId) || parsedId <= 0) {
      return NextResponse.json({ error: 'Invalid user id' }, { status: 400 });
    }
    userId = parsedId;
    // filename may include subdirectories like {userId}/uploads/avatar.webp
    filename = segments.slice(1).join('/');
  } else {
    // Single segment ÔÇö treat as filename; attempt to find owner via DB
    filename = segments[0] ?? 'default.png';
  }

  // ÔöÇÔöÇ Resolve user ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (userId === null) {
    // Try to find a user whose avatar matches this filename
    const user = await db.user.findFirst({
      where: { avatar: filename, deletedAt: null },
      select: { id: true },
    });
    if (user) {
      userId = user.id;
    }
    // If no user found, treat as a public / static avatar (default avatar fallthrough)
  }

  // ÔöÇÔöÇ Auth session (optional ÔÇö enriches response but not required for redirects) ÔöÇÔöÇ
  const session = await auth.api.getSession({ headers: request.headers });

  // ÔöÇÔöÇ Avatar not found ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (userId === null) {
    // No owner found ÔÇö serve default avatar
    return NextResponse.redirect(DEFAULT_AVATAR_URL, 302);
  }

  // Verify the user exists and is not deleted
  const user = await db.user.findFirst({
    where: { id: userId, deletedAt: null },
    select: { id: true, avatar: true },
  });

  if (!user) {
    return NextResponse.redirect(DEFAULT_AVATAR_URL, 302);
  }

  // If user has no avatar set, serve default
  if (!user.avatar) {
    return NextResponse.redirect(DEFAULT_AVATAR_URL, 302);
  }

  // Build S3 key: avatars/{userId}/{filename}
  const s3Key = `avatars/${userId}/${filename}`;

  try {
    const presignedUrl = await getPresignedDownloadUrl(s3Key, 3600);
    return NextResponse.redirect(presignedUrl, 302);
  } catch {
    // S3 key doesn't exist or access denied ÔÇö fall back to default
    return NextResponse.redirect(DEFAULT_AVATAR_URL, 302);
  }
}

// src/app/api/health/route.ts
import { NextResponse } from 'next/server';
import { db } from '@/server/db';

export async function GET() {
  const checks: Record<string, { status: string; latencyMs?: number }> = {};

  // Database
  const dbStart = Date.now();
  try {
    await db.$queryRaw`SELECT 1`;
    checks.database = { status: 'ok', latencyMs: Date.now() - dbStart };
  } catch (e) {
    checks.database = { status: 'error', latencyMs: Date.now() - dbStart };
  }

  // Disk space
  const mem = process.memoryUsage();
  checks.memory = {
    status: 'ok',
    latencyMs: Math.round(mem.heapUsed / 1024 / 1024),
  };

  const allHealthy = Object.values(checks).every((c) => c.status === 'ok');

  return NextResponse.json(
    {
      status: allHealthy ? 'ok' : 'degraded',
      timestamp: new Date().toISOString(),
      uptime: Math.round(process.uptime()),
      version: process.env.APP_VERSION ?? 'unknown',
      checks,
    },
    { status: allHealthy ? 200 : 503 },
  );
}

// src/app/api/images/[...path]/route.ts
// System image serving ÔÇö resolves S3 system image keys, serves presigned redirects

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/server/db';
import { getPresignedDownloadUrl } from '@/lib/s3';
import { checkRateLimit, RATE_LIMITS } from '@/lib/rate-limit';
import { getClientIp } from '@/lib/api-security';

const DEFAULT_IMAGE_URL =
  process.env.DEFAULT_IMAGE_URL ?? '/images/default.png';

function sanitizeSegment(seg: string): string | null {
  if (
    seg.includes('..') ||
    seg.includes('\0') ||
    seg.includes('/') ||
    seg.includes('\\')
  ) {
    return null;
  }
  if (!/^[a-zA-Z0-9._\-]+$/.test(seg)) {
    return null;
  }
  return seg;
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> },
) {
  // ÔöÇÔöÇ Rate limit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const ip = getClientIp(request);
  const rl = checkRateLimit(`image:${ip}`, RATE_LIMITS.api);
  if (!rl.allowed) {
    return NextResponse.json(
      { error: 'Too many requests' },
      {
        status: 429,
        headers: {
          'Retry-After': String(
            Math.ceil((rl.resetAt - Date.now()) / 1000),
          ),
        },
      },
    );
  }

  const { path } = await params;

  if (!path || path.length === 0) {
    return NextResponse.redirect(new URL(DEFAULT_IMAGE_URL, request.url));
  }

  // ÔöÇÔöÇ Sanitize path segments ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const segments: string[] = [];
  for (const seg of path) {
    const safe = sanitizeSegment(seg);
    if (!safe) {
      return NextResponse.redirect(new URL(DEFAULT_IMAGE_URL, request.url));
    }
    segments.push(safe);
  }

  const filename = segments[segments.length - 1];
  const s3Key = `images/${segments.join('/')}`;

  try {
    const presignedUrl = await getPresignedDownloadUrl(s3Key, 3600);
    return NextResponse.redirect(presignedUrl);
  } catch {
    return NextResponse.redirect(new URL(DEFAULT_IMAGE_URL, request.url));
  }
}

// src/app/api/webhook/stripe/route.ts
import { NextResponse } from 'next/server';
import { stripe } from '@/lib/stripe';
import { db } from '@/server/db';
import { logAuditEvent } from '@/server/auth/audit';

export const runtime = 'nodejs';

const WEBHOOK_SECRET = process.env.STRIPE_WEBHOOK_SECRET!;
const DEFAULT_STORAGE_GB = 5;

// ÔöÇÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Look up local User by Stripe customer id, then find-or-create Subscription. */
async function upsertSubscription(
  userId: number,
  sub: {
    id: string;
    status: string;
    items: { data: Array<{ price: { id: string; metadata: Record<string, string> }; quantity: number | null }> };
    trial_end: number | null;
    current_period_end: number | null;
    cancel_at_period_end: boolean;
  },
) {
  const plan = sub.items.data[0]?.price?.id ?? null;
  const storageGB = parseStorageFromMetadata(sub.items.data[0]?.price?.metadata) ?? DEFAULT_STORAGE_GB;

  const existing = await db.subscription.findFirst({
    where: { userId, stripeId: sub.id },
  });

  const subscriptionData = {
    name: sub.status,
    stripeStatus: sub.status,
    stripePlan: plan,
    quantity: sub.items.data[0]?.quantity ?? 1,
    trialEndsAt: sub.trial_end ? new Date(sub.trial_end * 1000) : null,
    endsAt: sub.current_period_end ? new Date(sub.current_period_end * 1000) : null,
  };

  const subscription = existing
    ? await db.subscription.update({ where: { id: existing.id }, data: subscriptionData })
    : await db.subscription.create({
        data: {
          userId,
          stripeId: sub.id,
          ...subscriptionData,
        },
      });

  // Sync subscription items
  for (const item of sub.items.data) {
    const itemStorage = parseStorageFromMetadata(item.price.metadata) ?? 0;
    const itemPlan = item.price.id;
    const itemQty = item.quantity ?? 1;

    await db.subscriptionItem.upsert({
      where: { subscriptionId_stripePlan: { subscriptionId: subscription.id, stripePlan: itemPlan } },
      create: { subscriptionId: subscription.id, stripeId: item.price.id, stripePlan: itemPlan, quantity: itemQty },
      update: { stripeId: item.price.id, quantity: itemQty },
    });
  }

  // Update user storage capacity
  await updateUserStorage(userId, storageGB);

  return subscription;
}

/** Parse storage capacity from Stripe price metadata (expects "storage_gb" key). */
function parseStorageFromMetadata(metadata: Record<string, string> | undefined): number | null {
  if (!metadata) return null;
  const val = metadata['storage_gb'] ?? metadata['storage'];
  const num = Number(val);
  return Number.isFinite(num) && num > 0 ? num : null;
}

/** Set UserSettings.storageCapacity, creating settings row if needed. */
async function updateUserStorage(userId: number, storageGB: number) {
  await db.userSettings.upsert({
    where: { userId },
    create: { userId, storageCapacity: storageGB },
    update: { storageCapacity: storageGB },
  });
}

/** Find local userId by Stripe customer id. */
async function getUserIdByStripeCustomer(stripeCustomerId: string): Promise<number | null> {
  const user = await db.user.findUnique({ where: { stripeId: stripeCustomerId }, select: { id: true } });
  return user?.id ?? null;
}

// ÔöÇÔöÇÔöÇ Event Handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

async function handleCheckoutSessionCompleted(session: any) {
  const customerId = session.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) {
    console.error('[stripe-webhook] checkout.session.completed: no local user for customer', customerId);
    return;
  }

  const subId = session.subscription as string | null;
  if (subId) {
    const sub = await stripe.subscriptions.retrieve(subId);
    await upsertSubscription(userId, sub as any);
  }

  await logAuditEvent(userId, 'subscription.created' as any, 'subscription', undefined, {
    stripeSessionId: session.id,
    stripeCustomerId: customerId,
    paymentStatus: session.payment_status,
  });
}

async function handleSubscriptionCreated(subscription: any) {
  const customerId = subscription.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) {
    console.error('[stripe-webhook] customer.subscription.created: no local user for customer', customerId);
    return;
  }

  await upsertSubscription(userId, subscription);

  await logAuditEvent(userId, 'subscription.created' as any, 'subscription', undefined, {
    stripeSubscriptionId: subscription.id,
    status: subscription.status,
  });
}

async function handleSubscriptionUpdated(subscription: any) {
  const customerId = subscription.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) {
    console.error('[stripe-webhook] customer.subscription.updated: no local user for customer', customerId);
    return;
  }

  await upsertSubscription(userId, subscription);

  await logAuditEvent(userId, 'subscription.updated' as any, 'subscription', undefined, {
    stripeSubscriptionId: subscription.id,
    status: subscription.status,
  });
}

async function handleSubscriptionDeleted(subscription: any) {
  const customerId = subscription.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) {
    console.error('[stripe-webhook] customer.subscription.deleted: no local user for customer', customerId);
    return;
  }

  await db.subscription.updateMany({
    where: { stripeId: subscription.id },
    data: {
      stripeStatus: 'canceled',
      endsAt: new Date(),
    },
  });

  // Reset to default storage
  await updateUserStorage(userId, DEFAULT_STORAGE_GB);

  await logAuditEvent(userId, 'subscription.deleted' as any, 'subscription', undefined, {
    stripeSubscriptionId: subscription.id,
  });
}

async function handleInvoicePaymentSucceeded(invoice: any) {
  const customerId = invoice.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) return;

  await logAuditEvent(userId, 'invoice.payment_succeeded' as any, 'invoice', undefined, {
    stripeInvoiceId: invoice.id,
    amountPaid: invoice.amount_paid,
    currency: invoice.currency,
    subscriptionId: invoice.subscription as string | null,
  });
}

async function handleInvoicePaymentFailed(invoice: any) {
  const customerId = invoice.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) return;

  await logAuditEvent(userId, 'invoice.payment_failed' as any, 'invoice', undefined, {
    stripeInvoiceId: invoice.id,
    amountDue: invoice.amount_due,
    currency: invoice.currency,
    attemptCount: invoice.attempt_count,
    subscriptionId: invoice.subscription as string | null,
  });
}

async function handleTrialWillEnd(subscription: any) {
  const customerId = subscription.customer as string;
  const userId = await getUserIdByStripeCustomer(customerId);
  if (!userId) return;

  await logAuditEvent(userId, 'subscription.trial_will_end' as any, 'subscription', undefined, {
    stripeSubscriptionId: subscription.id,
    trialEnd: subscription.trial_end,
    status: subscription.status,
  });
}

// ÔöÇÔöÇÔöÇ Route Handler ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

export async function POST(request: Request) {
  // Raw body required for Stripe signature verification
  const body = await request.text();
  const sig = request.headers.get('stripe-signature');

  if (!sig) {
    return NextResponse.json({ error: 'Missing stripe-signature header' }, { status: 400 });
  }

  if (!WEBHOOK_SECRET) {
    console.error('[stripe-webhook] STRIPE_WEBHOOK_SECRET is not configured');
    return NextResponse.json({ error: 'Webhook not configured' }, { status: 500 });
  }

  let event;
  try {
    event = stripe.webhooks.constructEvent(body, sig, WEBHOOK_SECRET);
  } catch (err: any) {
    console.error('[stripe-webhook] Signature verification failed:', err.message);
    return NextResponse.json({ error: `Webhook Error: ${err.message}` }, { status: 400 });
  }

  try {
    switch (event.type) {
      case 'checkout.session.completed':
        await handleCheckoutSessionCompleted(event.data.object);
        break;
      case 'customer.subscription.created':
        await handleSubscriptionCreated(event.data.object);
        break;
      case 'customer.subscription.updated':
        await handleSubscriptionUpdated(event.data.object);
        break;
      case 'customer.subscription.deleted':
        await handleSubscriptionDeleted(event.data.object);
        break;
      case 'invoice.payment_succeeded':
        await handleInvoicePaymentSucceeded(event.data.object);
        break;
      case 'invoice.payment_failed':
        await handleInvoicePaymentFailed(event.data.object);
        break;
      case 'customer.subscription.trial_will_end':
        await handleTrialWillEnd(event.data.object);
        break;
      default:
        // Unhandled event type ÔÇö acknowledge but skip
        console.log(`[stripe-webhook] Unhandled event type: ${event.type}`);
    }

    return NextResponse.json({ received: true }, { status: 200 });
  } catch (err: any) {
    console.error(`[stripe-webhook] Error processing ${event.type}:`, err);
    return NextResponse.json({ error: 'Webhook handler failed' }, { status: 500 });
  }
}

