function FileManagerInner() {
  const { currentFolderId, viewMode } = useFileManager();
  const { uploads, uploadFiles, clearDone } = useUpload();
  const [searchResults, setSearchResults] = useState<Array<{ uniqueId: number; name: string | null }> | null>(null);

  const { data: folders } = trpc.files.listFolders.useQuery({ parentId: currentFolderId });
  const { data: files } = trpc.files.listFiles.useQuery({ folderId: currentFolderId });

  const handleSearchResults = useCallback((results: Array<{ uniqueId: number; name: string | null }>) => {
    setSearchResults(results);
  }, []);

  const handleSearchClear = useCallback(() => {
    setSearchResults(null);
  }, []);

  return (
    <div className="flex h-full flex-col">
      <Breadcrumb />
      <Toolbar />
      <div className="flex flex-1 overflow-hidden">
        {/* Folder Tree Sidebar */}
        <div className="hidden w-56 shrink-0 overflow-y-auto border-r border-gray-200 bg-gray-50 p-3 dark:border-gray-700 dark:bg-gray-900 md:block">
          <h3 className="mb-2 text-xs font-semibold uppercase tracking-wider text-gray-500 dark:text-gray-400">
            Folders
          </h3>
          <FolderTree />
        </div>

        {/* Main content */}
        <div className="flex flex-1 flex-col overflow-hidden">
          <div className="px-4 py-2">
            <SearchBar onResults={handleSearchResults} onClear={handleSearchClear} />
          </div>
          <BulkActions />
          <UploadZone onFiles={uploadFiles}>
            <div className="flex-1 overflow-auto">
              {searchResults ? (
                <FileGrid folders={[]} files={searchResults as any} />
              ) : viewMode === 'grid' ? (
                <FileGrid folders={folders ?? []} files={files ?? []} />
              ) : (
                <FileList folders={folders ?? []} files={files ?? []} />
              )}
            </div>
          </UploadZone>
        </div>
      </div>
      <UploadProgress uploads={uploads} onClear={clearDone} />
    </div>
  );
}

export function FileManager() {
  return (
    <FileManagerProvider>
      <FileManagerInner />
    </FileManagerProvider>
  );
}

'use client';

import { useState, useCallback, type DragEvent } from 'react';
import { trpc } from '@/lib/trpc';
import { useFileManager } from './FileManagerContext';
import { Folder, ChevronRight, ChevronDown, Home } from 'lucide-react';

interface FolderNode {
  uniqueId: number;
  name: string | null;
  parentId: number;
}

export function FolderTree() {
  const { currentFolderId, setCurrentFolderId } = useFileManager();
  const [expanded, setExpanded] = useState<Set<number>>(new Set([0]));
  const [dropTarget, setDropTarget] = useState<number | null>(null);

  const { data: allFolders } = trpc.files.listAllFolders?.useQuery() ?? { data: [] };

  const moveItem = trpc.files.moveItems.useMutation({
    onSuccess: () => {
      setDropTarget(null);
    },
  });

  const toggleExpand = (id: number) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleDragOver = (e: DragEvent, folderId: number) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setDropTarget(folderId);
  };

  const handleDragLeave = () => {
    setDropTarget(null);
  };

  const handleDrop = (e: DragEvent, targetId: number) => {
    e.preventDefault();
    setDropTarget(null);
    try {
      const data = JSON.parse(e.dataTransfer.getData('application/json')) as {
        uniqueId: number;
        type: 'file' | 'folder';
      };
      if (data.uniqueId !== targetId) {
        const isFile = data.type === 'file';
        moveItem.mutate({
          folderIds: isFile ? [] : [data.uniqueId],
          fileIds: isFile ? [data.uniqueId] : [],
          targetFolderId: targetId,
        });
      }
    } catch {
      // invalid drag data
    }
  };

  const renderNode = (node: FolderNode, depth: number) => {
    const children = allFolders?.filter((f: FolderNode) => f.parentId === node.uniqueId) ?? [];
    const isExpanded = expanded.has(node.uniqueId);
    const isActive = currentFolderId === node.uniqueId;
    const isDropTargetHere = dropTarget === node.uniqueId;

    return (
      <div key={node.uniqueId}>
        <div
          onClick={() => setCurrentFolderId(node.uniqueId)}
          onDragOver={(e) => handleDragOver(e, node.uniqueId)}
          onDragLeave={handleDragLeave}
          onDrop={(e) => handleDrop(e, node.uniqueId)}
          className={`flex cursor-pointer items-center gap-1 rounded-md px-2 py-1.5 text-sm transition-colors ${
            isActive
              ? 'bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
              : isDropTargetHere
              ? 'bg-green-50 text-green-700 ring-2 ring-green-400 dark:bg-green-900/30 dark:text-green-400'
              : 'text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800'
          }`}
          style={{ paddingLeft: `${depth * 16 + 8}px` }}
        >
          {children.length > 0 ? (
            <button
              onClick={(e) => {
                e.stopPropagation();
                toggleExpand(node.uniqueId);
              }}
              className="rounded p-0.5 hover:bg-gray-200 dark:hover:bg-gray-700"
            >
              {isExpanded ? (
                <ChevronDown className="h-3.5 w-3.5" />
              ) : (
                <ChevronRight className="h-3.5 w-3.5" />
              )}
            </button>
          ) : (
            <span className="w-[18px]" />
          )}
          <Folder className="h-4 w-4 text-yellow-500" />
          <span className="truncate">{node.name ?? 'Unnamed'}</span>
        </div>
        {isExpanded && children.map((child: FolderNode) => renderNode(child, depth + 1))}
      </div>
    );
  };

  const rootFolders = allFolders?.filter((f: FolderNode) => f.parentId === 0) ?? [];

  return (
    <div className="space-y-1">
      {/* Root */}
      <div
        onClick={() => setCurrentFolderId(0)}
        onDragOver={(e) => handleDragOver(e, 0)}
        onDragLeave={handleDragLeave}
        onDrop={(e) => handleDrop(e, 0)}
        className={`flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-sm font-medium transition-colors ${
          currentFolderId === 0
            ? 'bg-blue-50 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
            : dropTarget === 0
            ? 'bg-green-50 text-green-700 ring-2 ring-green-400 dark:bg-green-900/30 dark:text-green-400'
            : 'text-gray-700 hover:bg-gray-100 dark:text-gray-300 dark:hover:bg-gray-800'
        }`}
      >
        <Home className="h-4 w-4" />
        <span>All Files</span>
      </div>

      {rootFolders.map((folder: FolderNode) => renderNode(folder, 1))}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { trpc } from '@/lib/trpc';
import { useToast } from '@/components/ui/toast';
import { useFileManager } from './FileManagerContext';
import { Folder, ChevronRight, ArrowLeft } from 'lucide-react';

interface MoveDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  itemIds: number[];
  currentFolderId: number;
}

export function MoveDialog({ open, onOpenChange, itemIds, currentFolderId }: MoveDialogProps) {
  const { toast } = useToast();
  const utils = trpc.useUtils();
  const [selectedFolderId, setSelectedFolderId] = useState<number | null>(null);
  const [parentId, setParentId] = useState(0);

  const { data: folders, isLoading } = trpc.files.listFolders.useQuery(
    { parentId },
    { enabled: open },
  );

  const moveItems = trpc.files.moveItems.useMutation({
    onSuccess: () => {
      toast(`${itemIds.length} item(s) moved`, 'success');
      utils.files.listFiles.invalidate();
      utils.files.listFolders.invalidate();
      onOpenChange(false);
    },
    onError: (err) => toast(err.message, 'error'),
  });

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="w-full max-w-md rounded-lg border border-gray-200 bg-white p-6 shadow-xl dark:border-gray-700 dark:bg-gray-900">
        <h2 className="mb-4 text-lg font-semibold text-gray-900 dark:text-white">Move to folder</h2>

        {isLoading ? (
          <div className="py-8 text-center text-sm text-gray-500">Loading folders...</div>
        ) : (
          <div className="max-h-64 overflow-y-auto rounded-lg border border-gray-200 dark:border-gray-700">
            {/* Root option */}
            <button
              onClick={() => setSelectedFolderId(0)}
              className={`flex w-full items-center gap-2 border-b border-gray-100 px-3 py-2 text-left text-sm hover:bg-gray-50 dark:border-gray-800 dark:hover:bg-gray-800 ${
                selectedFolderId === 0 ? 'bg-blue-50 dark:bg-blue-900/20' : ''
              }`}
            >
              <Folder className="h-4 w-4 text-gray-400" />
              <span className="text-gray-700 dark:text-gray-300">Root folder</span>
            </button>

            {folders?.map((folder) => (
              <button
                key={folder.uniqueId}
                onClick={() => setSelectedFolderId(folder.uniqueId)}
                className={`flex w-full items-center gap-2 border-b border-gray-100 px-3 py-2 text-left text-sm hover:bg-gray-50 dark:border-gray-800 dark:hover:bg-gray-800 ${
                  selectedFolderId === folder.uniqueId ? 'bg-blue-50 dark:bg-blue-900/20' : ''
                }`}
              >
                <Folder className="h-4 w-4 text-yellow-500" />
                <span className="text-gray-700 dark:text-gray-300">{folder.name ?? 'Unnamed'}</span>
              </button>
            ))}

            {!folders || folders.length === 0 ? (
              <div className="px-3 py-4 text-center text-xs text-gray-500">No folders here</div>
            ) : null}
          </div>
        )}

        <div className="mt-4 flex justify-end gap-2">
          <button
            onClick={() => onOpenChange(false)}
            className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-800"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              if (selectedFolderId !== null) {
                moveItems.mutate({
                  folderIds: itemIds.filter((id) => id > 0),
                  fileIds: [],
                  targetFolderId: selectedFolderId,
                });
              }
            }}
            disabled={selectedFolderId === null || moveItems.isPending}
            className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
          >
            {moveItems.isPending ? 'Moving...' : 'Move'}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useRef, useCallback } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Download, ZoomIn, ZoomOut, RotateCw, X, Maximize2, Play, Pause, Volume2 } from 'lucide-react';

interface PreviewModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  url: string;
  name: string;
  mimetype: string | null;
}

export function PreviewModal({ open, onOpenChange, url, name, mimetype }: PreviewModalProps) {
  const mime = mimetype ?? '';
  const isImage = mime.startsWith('image/');
  const isPdf = mime === 'application/pdf';
  const isVideo = mime.startsWith('video/');
  const isAudio = mime.startsWith('audio/');
  const isText = mime.startsWith('text/') || mime === 'application/json' || mime === 'application/xml';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-5xl p-0 dark:bg-gray-900">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-gray-200 px-4 py-3 dark:border-gray-700">
          <DialogTitle className="truncate text-sm font-medium text-gray-900 dark:text-white">
            {name}
          </DialogTitle>
          <div className="flex items-center gap-2">
            <a
              href={url}
              download={name}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20"
            >
              <Download className="h-3.5 w-3.5" />
              Download
            </a>
            <button
              onClick={() => onOpenChange(false)}
              className="rounded-md p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex min-h-[400px] items-center justify-center bg-gray-50 dark:bg-gray-950">
          {isImage && <ImageViewer url={url} name={name} />}
          {isPdf && <PdfViewer url={url} name={name} />}
          {isVideo && <VideoPlayer url={url} name={name} />}
          {isAudio && <AudioPlayer url={url} name={name} />}
          {isText && <TextViewer url={url} name={name} mime={mime} />}
          {!isImage && !isPdf && !isVideo && !isAudio && !isText && (
            <div className="p-8 text-center">
              <p className="text-sm text-gray-500 dark:text-gray-400">
                Preview not available for this file type.
              </p>
              <a
                href={url}
                download={name}
                className="mt-4 inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
              >
                <Download className="h-4 w-4" />
                Download to view
              </a>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

// ÔöÇÔöÇÔöÇ Image Viewer with Zoom/Pan ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function ImageViewer({ url, name }: { url: string; name: string }) {
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const lastPos = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    lastPos.current = { x: e.clientX - position.x, y: e.clientY - position.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({
      x: e.clientX - lastPos.current.x,
      y: e.clientY - lastPos.current.y,
    });
  };

  const handleMouseUp = () => setIsDragging(false);

  const reset = () => {
    setZoom(1);
    setRotation(0);
    setPosition({ x: 0, y: 0 });
  };

  return (
    <div className="relative w-full">
      {/* Controls */}
      <div className="absolute right-2 top-2 z-10 flex gap-1 rounded-lg border border-gray-200 bg-white p-1 shadow-sm dark:border-gray-700 dark:bg-gray-800">
        <button
          onClick={() => setZoom((z) => Math.min(z + 0.25, 5))}
          className="rounded p-1 text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700"
          title="Zoom in"
        >
          <ZoomIn className="h-4 w-4" />
        </button>
        <button
          onClick={() => setZoom((z) => Math.max(z - 0.25, 0.25))}
          className="rounded p-1 text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700"
          title="Zoom out"
        >
          <ZoomOut className="h-4 w-4" />
        </button>
        <button
          onClick={() => setRotation((r) => r + 90)}
          className="rounded p-1 text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700"
          title="Rotate"
        >
          <RotateCw className="h-4 w-4" />
        </button>
        <button
          onClick={reset}
          className="rounded p-1 text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700"
          title="Reset"
        >
          <Maximize2 className="h-4 w-4" />
        </button>
      </div>

      {/* Zoom indicator */}
      <div className="absolute bottom-2 left-2 z-10 rounded bg-black/50 px-2 py-1 text-xs text-white">
        {Math.round(zoom * 100)}%
      </div>

      {/* Image */}
      <div
        className="flex min-h-[400px] items-center justify-center overflow-hidden cursor-grab active:cursor-grabbing"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        <img
          src={url}
          alt={name}
          className="max-h-[65vh] select-none transition-transform"
          style={{
            transform: `translate(${position.x}px, ${position.y}px) scale(${zoom}) rotate(${rotation}deg)`,
          }}
          draggable={false}
        />
      </div>
    </div>
  );
}

// ÔöÇÔöÇÔöÇ PDF Viewer ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
