// src/components/file-manager/RenameDialog.tsx
'use client';

import { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { trpc } from '@/lib/trpc';
import { useFileManager } from './FileManagerContext';
import { useToast } from '@/components/ui/toast';

interface RenameDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  itemId: number;
  itemType: 'folder' | 'file';
  currentName: string;
}

export function RenameDialog({ open, onOpenChange, itemId, itemType, currentName }: RenameDialogProps) {
  const [name, setName] = useState(currentName);
  const { currentFolderId } = useFileManager();
  const { toast } = useToast();
  const utils = trpc.useUtils();

  useEffect(() => {
    if (open) {
      setName(currentName);
    }
  }, [open, currentName]);

  const rename = trpc.files.renameItem.useMutation({
    onSuccess: () => {
      toast('Renamed successfully', 'success');
      utils.files.listFolders.invalidate({ parentId: currentFolderId });
      utils.files.listFiles.invalidate({ folderId: currentFolderId });
      onOpenChange(false);
    },
    onError: (error) => toast(error.message, 'error'),
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Rename {itemType === 'folder' ? 'Folder' : 'File'}</DialogTitle>
        </DialogHeader>
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && name.trim() && name !== currentName) {
              rename.mutate({ uniqueId: itemId, name: name.trim(), type: itemType });
            }
          }}
          className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
          autoFocus
        />
        <DialogFooter>
          <button onClick={() => onOpenChange(false)} className="rounded-md border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50">
            Cancel
          </button>
          <button
            onClick={() => {
              if (name.trim() && name !== currentName) {
                rename.mutate({ uniqueId: itemId, name: name.trim(), type: itemType });
              }
            }}
            disabled={!name.trim() || name === currentName || rename.isPending}
            className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
          >
            Rename
          </button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, X, SlidersHorizontal, ArrowUpDown } from 'lucide-react';
import { trpc } from '@/lib/trpc';

type FileType = 'all' | 'image' | 'document' | 'video' | 'audio' | 'other';
type SortBy = 'name' | 'date' | 'size';
type SortOrder = 'asc' | 'desc';

interface SearchBarProps {
  onResults: (files: Array<{ uniqueId: number; name: string | null }>) => void;
  onClear: () => void;
}

const fileTypeOptions: { value: FileType; label: string }[] = [
  { value: 'all', label: 'All types' },
  { value: 'image', label: 'Images' },
  { value: 'document', label: 'Documents' },
  { value: 'video', label: 'Videos' },
  { value: 'audio', label: 'Audio' },
  { value: 'other', label: 'Other' },
];

const mimePrefixes: Record<FileType, string[]> = {
  image: ['image/'],
  document: ['application/pdf', 'application/msword', 'application/vnd', 'text/'],
  video: ['video/'],
  audio: ['audio/'],
  other: [],
  all: [],
};

export function SearchBar({ onResults, onClear }: SearchBarProps) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const [fileType, setFileType] = useState<FileType>('all');
  const [sortBy, setSortBy] = useState<SortBy>('name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');
  const [showFilters, setShowFilters] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 300);
    return () => clearTimeout(timer);
  }, [query]);

  const { data: results } = trpc.files.search.useQuery(
    { query: debouncedQuery },
    { enabled: debouncedQuery.length >= 2 },
  );

  // Apply client-side filters and sorting
  useEffect(() => {
    if (!results) {
      onClear();
      return;
    }

    let filtered = results;

    // Filter by file type
    if (fileType !== 'all') {
      const prefixes = mimePrefixes[fileType];
      filtered = filtered.filter((f) => {
        if (!f.mimetype) return fileType === 'other';
        return prefixes.some((p) => f.mimetype?.startsWith(p));
      });
    }

    // Sort
    filtered = [...filtered].sort((a, b) => {
      let cmp = 0;
      switch (sortBy) {
        case 'name':
          cmp = (a.name ?? '').localeCompare(b.name ?? '');
          break;
        case 'date':
          cmp = new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
          break;
        case 'size':
          cmp = Number(a.filesize ?? '0') - Number(b.filesize ?? '0');
          break;
      }
      return sortOrder === 'asc' ? cmp : -cmp;
    });

    onResults(filtered);
  }, [results, fileType, sortBy, sortOrder]);

  const handleClear = useCallback(() => {
    setQuery('');
    setDebouncedQuery('');
    setFileType('all');
    onClear();
  }, [onClear]);

  const toggleSortOrder = () => {
    setSortOrder((o) => (o === 'asc' ? 'desc' : 'asc'));
  };

  return (
    <div className="space-y-2">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search files by name..."
          className="w-full rounded-lg border border-gray-300 bg-white py-2 pl-10 pr-16 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white dark:placeholder-gray-400"
        />
        <div className="absolute right-2 top-1/2 flex -translate-y-1/2 items-center gap-1">
          {query && (
            <button
              onClick={handleClear}
              className="rounded p-0.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
            >
              <X className="h-4 w-4" />
            </button>
          )}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`rounded p-1 ${
              showFilters ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
            }`}
          >
            <SlidersHorizontal className="h-4 w-4" />
          </button>
          <button
            onClick={toggleSortOrder}
            className="rounded p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
            title={`Sort ${sortOrder === 'asc' ? 'ascending' : 'descending'}`}
          >
            <ArrowUpDown className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className="flex flex-wrap items-center gap-3 rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 dark:border-gray-700 dark:bg-gray-800/50">
          {/* File type */}
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Type:</span>
            <div className="flex gap-1">
              {fileTypeOptions.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setFileType(opt.value)}
                  className={`rounded-md px-2 py-1 text-xs font-medium transition-colors ${
                    fileType === opt.value
                      ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                      : 'text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          {/* Sort by */}
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-gray-500 dark:text-gray-400">Sort:</span>
            <div className="flex gap-1">
              {(['name', 'date', 'size'] as SortBy[]).map((s) => (
                <button
                  key={s}
                  onClick={() => setSortBy(s)}
                  className={`rounded-md px-2 py-1 text-xs font-medium capitalize transition-colors ${
                    sortBy === s
                      ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                      : 'text-gray-600 hover:bg-gray-100 dark:text-gray-400 dark:hover:bg-gray-700'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>

          {debouncedQuery && results && (
            <span className="text-xs text-gray-500 dark:text-gray-400">
              {results.length} result(s)
            </span>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { trpc } from '@/lib/trpc';
import { useToast } from '@/components/ui/toast';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Copy, Link, Shield, Clock, Lock } from 'lucide-react';

interface ShareDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  itemId: number;
  type: 'file' | 'folder';
  itemName: string;
}

export function ShareDialog({ open, onOpenChange, itemId, type, itemName }: ShareDialogProps) {
  const { toast } = useToast();
  const utils = trpc.useUtils();
  const [permission, setPermission] = useState<'visitor' | 'editor'>('visitor');
  const [isProtected, setIsProtected] = useState(false);
  const [password, setPassword] = useState('');
  const [expireIn, setExpireIn] = useState<number | undefined>(undefined);
  const [shareUrl, setShareUrl] = useState<string | null>(null);

  const createShare = trpc.files.createShare.useMutation({
    onSuccess: (data) => {
      setShareUrl(data.url);
      toast('Share link created', 'success');
      utils.files.listShares.invalidate();
    },
    onError: (err) => toast(err.message, 'error'),
  });

  const handleCreate = () => {
    createShare.mutate({
      itemId,
      type,
      permission,
      protected: isProtected,
      password: isProtected ? password : undefined,
      expireIn,
    });
  };

  const copyUrl = () => {
    if (shareUrl) {
      navigator.clipboard.writeText(shareUrl);
      toast('Link copied to clipboard', 'success');
    }
  };

  const handleClose = () => {
    setShareUrl(null);
    setPermission('visitor');
    setIsProtected(false);
    setPassword('');
    setExpireIn(undefined);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Share "{itemName}"</DialogTitle>
        </DialogHeader>

        {shareUrl ? (
          <div className="space-y-4">
            <div className="flex items-center gap-2 rounded-lg border border-gray-200 bg-gray-50 p-3">
              <Link className="h-4 w-4 text-gray-400" />
              <input
                readOnly
                value={shareUrl}
                className="flex-1 bg-transparent text-sm text-gray-700 outline-none"
              />
              <button onClick={copyUrl} className="rounded p-1 text-gray-400 hover:text-gray-600">
                <Copy className="h-4 w-4" />
              </button>
            </div>
            <p className="text-xs text-gray-500">
              Anyone with this link can {permission === 'editor' ? 'view, download, and upload to' : 'view and download'} this {type}.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                <Shield className="mr-1 inline h-4 w-4" />
                Permission
              </label>
              <div className="flex gap-2">
                <button
                  onClick={() => setPermission('visitor')}
                  className={`flex-1 rounded-lg border px-3 py-2 text-sm ${
                    permission === 'visitor'
                      ? 'border-blue-500 bg-blue-50 text-blue-700'
                      : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  Visitor (read-only)
                </button>
                <button
                  onClick={() => setPermission('editor')}
                  className={`flex-1 rounded-lg border px-3 py-2 text-sm ${
                    permission === 'editor'
                      ? 'border-blue-500 bg-blue-50 text-blue-700'
                      : 'border-gray-200 text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  Editor (can upload)
                </button>
              </div>
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                <Lock className="mr-1 inline h-4 w-4" />
                Password Protection
              </label>
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={isProtected}
                  onChange={(e) => setIsProtected(e.target.checked)}
                  className="h-4 w-4 rounded border-gray-300"
                />
                <span className="text-sm text-gray-600">Require password</span>
              </div>
              {isProtected && (
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter password"
                  className="mt-2 w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                />
              )}
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">
                <Clock className="mr-1 inline h-4 w-4" />
                Expiration
              </label>
              <select
                value={expireIn ?? ''}
                onChange={(e) => setExpireIn(e.target.value ? Number(e.target.value) : undefined)}
                className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              >
                <option value="">Never expires</option>
                <option value="1">1 hour</option>
                <option value="24">24 hours</option>
                <option value="168">7 days</option>
                <option value="720">30 days</option>
              </select>
            </div>
          </div>
        )}

        <DialogFooter>
          <button
            onClick={handleClose}
            className="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
          >
            {shareUrl ? 'Done' : 'Cancel'}
          </button>
          {!shareUrl && (
            <button
              onClick={handleCreate}
              disabled={createShare.isPending || (isProtected && !password)}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
            >
              {createShare.isPending ? 'Creating...' : 'Create Link'}
            </button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

