// Admin guard: only ADMIN+ (level >= 80)
const adminProcedure = protectedProcedure.use(async ({ ctx, next }) => {
  const role = (ctx.session.user as Record<string, unknown>).role;
  if (role !== 'admin') {
    throw new TRPCError({ code: 'FORBIDDEN', message: 'Admin access required' });
  }
  return next({ ctx });
});

export const adminRouter = router({
  // ÔöÇÔöÇÔöÇ Dashboard ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getDashboardStats: adminProcedure.query(async ({ ctx }) => {
    const { cached, CACHE_KEYS } = await import('@/lib/cache');
    return cached(CACHE_KEYS.DASHBOARD_STATS, async () => {
      const totalUsers = await ctx.db.user.count();
      const totalFiles = await ctx.db.fileManagerFile.count({ where: { deletedAt: null } });
      const totalFolders = await ctx.db.fileManagerFolder.count({ where: { deletedAt: null } });

      const files = await ctx.db.fileManagerFile.findMany({
        where: { deletedAt: null },
        select: { filesize: true },
      });
      const storageUsed = files.reduce((sum: number, f: { filesize: string | null }) => sum + Number(f.filesize ?? '0'), 0);

      const recentUsers = await ctx.db.user.findMany({
        orderBy: { createdAt: 'desc' },
        take: 10,
        select: { id: true, name: true, email: true, createdAt: true },
      });

      return {
        totalUsers,
        totalFiles,
        totalFolders,
        storageUsed: Number(storageUsed),
        recentUsers,
      };
    }, 30_000); // cache for 30 seconds
  }),

  // ÔöÇÔöÇÔöÇ User Management ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  listUsers: adminProcedure
    .input(z.object({
      search: z.string().optional(),
      page: z.number().default(1),
      limit: z.number().default(10),
    }))
    .query(async ({ ctx, input }) => {
      const where = input.search
        ? {
            OR: [
              { name: { contains: input.search, mode: 'insensitive' as const } },
              { email: { contains: input.search, mode: 'insensitive' as const } },
            ],
          }
        : {};

      const [users, total] = await Promise.all([
        ctx.db.user.findMany({
          where,
          skip: (input.page - 1) * input.limit,
          take: input.limit,
          orderBy: { createdAt: 'desc' },
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
            createdAt: true,
          },
        }),
        ctx.db.user.count({ where }),
      ]);

      return { users, total, pages: Math.ceil(total / input.limit) };
    }),

  getUser: adminProcedure
    .input(z.object({ userId: z.number() }))
    .query(async ({ ctx, input }) => {
      const user = await ctx.db.user.findUnique({
        where: { id: input.userId },
        select: {
          id: true,
          name: true,
          email: true,
          role: true,
          createdAt: true,
          settings: true,
        },
      });
      if (!user) throw new TRPCError({ code: 'NOT_FOUND', message: 'User not found' });

      const fileCount = await ctx.db.fileManagerFile.count({
        where: { userId: input.userId, deletedAt: null },
      });
      const folderCount = await ctx.db.fileManagerFolder.count({
        where: { userId: input.userId, deletedAt: null },
      });

      const files = await ctx.db.fileManagerFile.findMany({
        where: { userId: input.userId, deletedAt: null },
        select: { filesize: true },
      });
      const storageUsed = files.reduce((sum, f) => sum + BigInt(f.filesize ?? '0'), BigInt(0));

      return {
        ...user,
        fileCount,
        folderCount,
        storageUsed: Number(storageUsed),
      };
    }),

  updateUser: adminProcedure
    .input(z.object({
      userId: z.number(),
      name: z.string().optional(),
      email: z.string().email().optional(),
      role: z.enum(['admin', 'user']).optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const user = await ctx.db.user.update({
        where: { id: input.userId },
        data: {
          ...(input.name && { name: input.name }),
          ...(input.email && { email: input.email }),
          ...(input.role && { role: input.role }),
        },
      });
      return { user };
    }),

  deleteUser: adminProcedure
    .input(z.object({ userId: z.number() }))
    .mutation(async ({ ctx, input }) => {
      // Delete user's files from S3
      const files = await ctx.db.fileManagerFile.findMany({
        where: { userId: input.userId },
      });
      const { getS3Key, deleteObject } = await import('@/lib/s3');
      for (const file of files) {
        const key = getS3Key(input.userId, file.uniqueId, file.basename ?? file.name ?? 'unknown');
        await deleteObject(key);
      }

      // Cascade delete
      await ctx.db.fileManagerFile.deleteMany({ where: { userId: input.userId } });
      await ctx.db.fileManagerFolder.deleteMany({ where: { userId: input.userId } });
      await ctx.db.share.deleteMany({ where: { userId: input.userId } });
      await ctx.db.favouriteFolder.deleteMany({ where: { userId: input.userId } });
      await ctx.db.userSettings.deleteMany({ where: { userId: input.userId } });
      await ctx.db.user.delete({ where: { id: input.userId } });

      return { success: true };
    }),

  changeUserRole: adminProcedure
    .input(z.object({ userId: z.number(), role: z.enum(['admin', 'user']) }))
    .mutation(async ({ ctx, input }) => {
      const user = await ctx.db.user.update({
        where: { id: input.userId },
        data: { role: input.role },
      });
      return { user };
    }),

  changeStorageCapacity: adminProcedure
    .input(z.object({ userId: z.number(), capacity: z.number().min(1).max(1000) }))
    .mutation(async ({ ctx, input }) => {
      await ctx.db.userSettings.upsert({
        where: { userId: input.userId },
        update: { storageCapacity: input.capacity },
        create: { userId: input.userId, storageCapacity: input.capacity },
      });
      return { success: true };
    }),

  createUser: adminProcedure
    .input(z.object({
      name: z.string().min(1),
      email: z.string().email(),
      password: z.string().min(8),
      role: z.enum(['admin', 'master', 'editor', 'viewer']).default('viewer'),
    }))
    .mutation(async ({ ctx, input }) => {
      // Check if email already exists
      const existing = await ctx.db.user.findUnique({ where: { email: input.email } });
      if (existing) {
        throw new TRPCError({ code: 'CONFLICT', message: 'Email already in use' });
      }

      // Create user with bcrypt-hashed password (compatible with BetterAuth)
      const { hashPassword } = await import('better-auth/crypto');
      const hashedPassword = await hashPassword(input.password);

      const user = await ctx.db.user.create({
        data: {
          name: input.name,
          email: input.email,
          password: hashedPassword,
          role: input.role,
        },
      });

        // Create default settings
        await ctx.db.userSettings.create({
          data: { userId: user.id, storageCapacity: 5 },
        });

        await logAuditEvent(
          Number(ctx.session.user.id),
          'admin.user_created',
          'user',
          user.id,
          { email: input.email, role: input.role },
        );

      return { success: true, userId: user.id };
    }),

  newRegistrations: adminProcedure.query(async ({ ctx }) => {
    const now = new Date();
    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    const [last7Days, last30Days] = await Promise.all([
      ctx.db.user.count({ where: { createdAt: { gte: sevenDaysAgo } } }),
      ctx.db.user.count({ where: { createdAt: { gte: thirtyDaysAgo } } }),
    ]);

    return { last7Days, last30Days };
  }),

  // ÔöÇÔöÇÔöÇ Settings ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getSettings: adminProcedure.query(async ({ ctx }) => {
    const { cached, CACHE_KEYS } = await import('@/lib/cache');
    return cached(CACHE_KEYS.SETTINGS, async () => {
      const settings = await ctx.db.setting.findMany();
      const map: Record<string, string> = {};
      for (const s of settings) {
        map[s.name] = s.value ?? '';
      }
      return map;
    }, 60_000); // cache for 1 minute
  }),

  updateSettings: adminProcedure
    .input(z.object({
      settings: z.record(z.string(), z.string()),
    }))
    .mutation(async ({ ctx, input }) => {
      for (const [name, value] of Object.entries(input.settings)) {
        await ctx.db.setting.upsert({
          where: { name },
          update: { value },
          create: { name, value },
        });
      }
      // Invalidate settings cache
      const { invalidateCache, CACHE_KEYS } = await import('@/lib/cache');
      invalidateCache(CACHE_KEYS.SETTINGS);
      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Languages ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  listLanguages: adminProcedure.query(async ({ ctx }) => {
    return ctx.db.language.findMany({ orderBy: { name: 'asc' } });
  }),

  createLanguage: adminProcedure
    .input(z.object({ name: z.string().min(1), locale: z.string().min(2).max(5) }))
    .mutation(async ({ ctx, input }) => {
      const lang = await ctx.db.language.create({ data: input });
      return { language: lang };
    }),

  deleteLanguage: adminProcedure
    .input(z.object({ id: z.string() }))
    .mutation(async ({ ctx, input }) => {
      await ctx.db.languageString.deleteMany({ where: { languageId: input.id } });
      await ctx.db.language.delete({ where: { id: input.id } });
      return { success: true };
    }),

  listTranslations: adminProcedure
    .input(z.object({ languageId: z.string() }))
    .query(async ({ ctx, input }) => {
      return ctx.db.languageString.findMany({
        where: { languageId: input.languageId },
        orderBy: { key: 'asc' },
      });
    }),

  updateTranslation: adminProcedure
    .input(z.object({
      lang: z.string(),
      key: z.string(),
      value: z.string(),
    }))
    .mutation(async ({ ctx, input }) => {
      const lang = await ctx.db.language.findUnique({ where: { locale: input.lang } });
      if (!lang) throw new TRPCError({ code: 'NOT_FOUND', message: 'Language not found' });

      const existing = await ctx.db.languageString.findFirst({
        where: { languageId: lang.id, key: input.key },
      });
      if (existing) {
        await ctx.db.languageString.update({
          where: { id: existing.id },
          data: { value: input.value },
        });
      } else {
        await ctx.db.languageString.create({
          data: { languageId: lang.id, key: input.key, value: input.value },
        });
      }
      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Pages ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  listPages: adminProcedure.query(async ({ ctx }) => {
    return ctx.db.page.findMany({ orderBy: { title: 'asc' } });
  }),

  getPage: adminProcedure
    .input(z.object({ slug: z.string() }))
    .query(async ({ ctx, input }) => {
      const page = await ctx.db.page.findUnique({ where: { slug: input.slug } });
      if (!page) throw new TRPCError({ code: 'NOT_FOUND', message: 'Page not found' });
      return page;
    }),

  updatePage: adminProcedure
    .input(z.object({
      slug: z.string(),
      title: z.string().optional(),
      content: z.string().optional(),
      visibility: z.boolean().optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const page = await ctx.db.page.update({
        where: { slug: input.slug },
        data: {
          ...(input.title && { title: input.title }),
          ...(input.content !== undefined && { content: input.content }),
          ...(input.visibility !== undefined && { visibility: input.visibility }),
        },
      });
      return { page };
    }),

  // ÔöÇÔöÇÔöÇ Maintenance ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getSystemInfo: adminProcedure.query(async ({ ctx }) => {
    const totalUsers = await ctx.db.user.count();
    const totalFiles = await ctx.db.fileManagerFile.count({ where: { deletedAt: null } });
    const totalFolders = await ctx.db.fileManagerFolder.count({ where: { deletedAt: null } });
    const totalSubscriptions = await ctx.db.subscription.count();

    return {
      version: process.env.APP_VERSION ?? '0.1.0',
      nodeVersion: process.version,
      platform: process.platform,
      uptime: process.uptime(),
      totalUsers,
      totalFiles,
      totalFolders,
      totalSubscriptions,
    };
  }),

  healthCheck: adminProcedure.query(async ({ ctx }) => {
    const checks: Record<string, string> = {};

    try {
      await ctx.db.$queryRaw`SELECT 1`;
      checks.database = 'ok';
    } catch {
      checks.database = 'error';
    }

    const allOk = Object.values(checks).every((v) => v === 'ok');

    return {
      status: allOk ? 'healthy' : 'degraded',
      checks,
      timestamp: new Date().toISOString(),
    };
  }),

  clearCache: adminProcedure.mutation(async () => {
    return { success: true, message: 'Cache cleared' };
  }),

  // ÔöÇÔöÇÔöÇ Analytics ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  analyticsOverview: adminProcedure.query(async ({ ctx }) => {
    const [totalUsers, totalFiles, totalFolders, totalStorage, recentUsers, activeShares] =
      await Promise.all([
        ctx.db.user.count(),
        ctx.db.fileManagerFile.count({ where: { deletedAt: null } }),
        ctx.db.fileManagerFolder.count({ where: { deletedAt: null } }),
        ctx.db.userSettings.aggregate({ _sum: { storageCapacity: true } }),
        ctx.db.user.count({
          where: {
            createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
          },
        }),
        ctx.db.share.count(),
      ]);

    return {
      totalUsers,
      totalFiles,
      totalFolders,
      totalStorageGB: totalStorage._sum.storageCapacity ?? 0,
      recentUsers,
      activeShares,
    };
  }),

  analyticsUserGrowth: adminProcedure.query(async ({ ctx }) => {
    // Get user registrations grouped by day for last 30 days
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const users = await ctx.db.user.findMany({
      where: { createdAt: { gte: thirtyDaysAgo } },
      select: { createdAt: true },
      orderBy: { createdAt: 'asc' },
    });

    // Group by date
    const grouped: Record<string, number> = {};
    for (const user of users) {
      const day = user.createdAt.toISOString().split('T')[0] ?? 'unknown';
      grouped[day] = (grouped[day] ?? 0) + 1;
    }

    return Object.entries(grouped).map(([date, count]) => ({ date, count }));
  }),

  analyticsFileTypeDistribution: adminProcedure.query(async ({ ctx }) => {
    const files = await ctx.db.fileManagerFile.findMany({
      where: { deletedAt: null },
      select: { mimetype: true },
    });

    const categories = {
      Images: 0,
      Documents: 0,
      Videos: 0,
      Audio: 0,
      Other: 0,
    };

    for (const file of files) {
      const mime = file.mimetype ?? '';
      if (mime.startsWith('image/')) categories.Images += 1;
      else if (mime.startsWith('video/')) categories.Videos += 1;
      else if (mime.startsWith('audio/')) categories.Audio += 1;
      else if (mime.includes('pdf') || mime.includes('word') || mime.includes('text') || mime.includes('sheet')) categories.Documents += 1;
      else categories.Other += 1;
    }

    return Object.entries(categories)
      .filter(([, count]) => count > 0)
      .map(([type, count]) => ({ type, count }));
  }),

  analyticsStorageByUser: adminProcedure.query(async ({ ctx }) => {
    const users = await ctx.db.user.findMany({
      select: {
        id: true,
        name: true,
        email: true,
        settings: { select: { storageCapacity: true } },
      },
      take: 20,
    });

    // Count files per user
    const fileCounts = await ctx.db.fileManagerFile.groupBy({
      by: ['userId'],
      where: { deletedAt: null },
      _count: { id: true },
      orderBy: { _count: { id: 'desc' } },
      take: 20,
    });

    const countMap = new Map(fileCounts.map((f) => [f.userId, f._count.id]));

    return users.map((u) => ({
      userId: u.id,
      name: u.name ?? 'Unknown',
      email: u.email,
      storageGB: u.settings?.storageCapacity ?? 0,
      fileCount: countMap.get(u.id) ?? 0,
    }));
  }),

  analyticsShareStats: adminProcedure.query(async ({ ctx }) => {
    const [total, passwordProtected, expired] = await Promise.all([
      ctx.db.share.count(),
      ctx.db.share.count({ where: { protected: true } }),
      // Count expired (shares with expireIn set and createdAt + expireIn < now)
      ctx.db.share.findMany({
        where: { expireIn: { not: null } },
        select: { createdAt: true, expireIn: true },
      }).then((shares) =>
        shares.filter((s) => {
          const expiresAt = new Date(s.createdAt);
          expiresAt.setHours(expiresAt.getHours() + (s.expireIn ?? 0));
          return expiresAt < new Date();
        }).length,
      ),
    ]);

    return {
      total,
      passwordProtected,
      expired,
      active: total - expired,
    };
  }),

  // ÔöÇÔöÇÔöÇ Exports ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  exportUsers: adminProcedure.query(async ({ ctx }) => {
    const users = await ctx.db.user.findMany({
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
        settings: { select: { storageCapacity: true } },
      },
      orderBy: { createdAt: 'desc' },
    });

    const fileCounts = await ctx.db.fileManagerFile.groupBy({
      by: ['userId'],
      where: { deletedAt: null },
      _count: { id: true },
    });
    const countMap = new Map(fileCounts.map((f) => [f.userId, f._count.id]));

    return users.map((u) => ({
      id: u.id,
      name: u.name,
      email: u.email,
      role: u.role,
      createdAt: u.createdAt,
      storageGB: u.settings?.storageCapacity ?? 0,
      fileCount: countMap.get(u.id) ?? 0,
    }));
  }),

  exportFiles: adminProcedure.query(async ({ ctx }) => {
    const files = await ctx.db.fileManagerFile.findMany({
      where: { deletedAt: null },
      orderBy: { createdAt: 'desc' },
    });
    return files;
  }),

  exportShares: adminProcedure.query(async ({ ctx }) => {
    const shares = await ctx.db.share.findMany({
      orderBy: { createdAt: 'desc' },
    });
    return shares;
  }),

  // ÔöÇÔöÇÔöÇ Admin Password Reset ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  resetUserPassword: adminProcedure
    .input(z.object({ userId: z.number() }))
    .mutation(async ({ ctx, input }) => {
      const user = await ctx.db.user.findUnique({ where: { id: input.userId } });
      if (!user) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'User not found' });
      }

      // Use BetterAuth to send password reset email
      const { auth } = await import('@/server/auth');
      await auth.api.requestPasswordReset({
        body: {
          email: user.email,
          redirectTo: '/reset-password',
        },
      });

      await logAuditEvent(
        Number(ctx.session.user.id),
        'admin.password_reset',
        'user',
        input.userId,
      );

      return { success: true, message: `Password reset email sent to ${user.email}` };
    }),

  // ÔöÇÔöÇÔöÇ Admin Invoices ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  listInvoices: adminProcedure.query(async ({ ctx }) => {
    const invoices = await ctx.db.invoice.findMany({
      orderBy: { createdAt: 'desc' },
      include: { user: { select: { id: true, name: true, email: true } } },
    });
    return invoices;
  }),

  getUserInvoices: adminProcedure
    .input(z.object({ userId: z.number() }))
    .query(async ({ ctx, input }) => {
      const invoices = await ctx.db.invoice.findMany({
        where: { userId: input.userId },
        orderBy: { createdAt: 'desc' },
      });
      return invoices;
    }),

  createInvoice: adminProcedure
    .input(z.object({
      userId: z.number(),
      order: z.string(),
      planId: z.string(),
      seller: z.record(z.string(), z.unknown()),
      client: z.record(z.string(), z.unknown()),
      bag: z.array(z.record(z.string(), z.unknown())),
      total: z.string(),
      currency: z.string().default('usd'),
      notes: z.string().optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const token = Math.random().toString(36).substring(2, 18);
      const invoice = await ctx.db.invoice.create({
        data: {
          token,
          order: input.order,
          provider: 'stripe',
          userId: input.userId,
          planId: input.planId,
          seller: input.seller as any,
          client: input.client as any,
          bag: input.bag as any,
          total: input.total,
          currency: input.currency,
          notes: input.notes,
        },
      });
      return invoice;
    }),

  deleteInvoice: adminProcedure
    .input(z.object({ invoiceId: z.number() }))
    .mutation(async ({ ctx, input }) => {
      await ctx.db.invoice.delete({ where: { id: input.invoiceId } });
      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Support Form ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  sendSupportMessage: adminProcedure
    .input(z.object({
      subject: z.string().min(1).max(255),
      message: z.string().min(10),
      priority: z.enum(['low', 'medium', 'high']).default('medium'),
    }))
    .mutation(async ({ ctx, input }) => {
      const adminEmail = process.env.ADMIN_EMAIL ?? 'admin@tutiscloud.com';

      // Send support notification to admin
      const { sendSharedLinkEmail } = await import('@/lib/email/resend');
      const { Resend } = await import('resend');
      const resend = new Resend(process.env.RESEND_API_KEY);
      const FROM_ADDRESS = process.env.EMAIL_FROM ?? 'TutisCloud <noreply@tutiscloud.com>';

      const user = await ctx.db.user.findUnique({
        where: { id: Number(ctx.session.user.id) },
      });

      await resend.emails.send({
        from: FROM_ADDRESS,
        to: adminEmail,
        subject: `[Support ${input.priority.toUpperCase()}] ${input.subject}`,
        html: `
          <h2>Support Request</h2>
          <p><strong>From:</strong> ${user?.name ?? 'Unknown'} (${user?.email ?? 'unknown'})</p>
          <p><strong>Priority:</strong> ${input.priority}</p>
          <hr />
          <p>${input.message.replace(/\n/g, '<br/>')}</p>
        `,
      });

      await logAuditEvent(
        Number(ctx.session.user.id),
        'support.message_sent',
        'support',
        undefined,
        { subject: input.subject, priority: input.priority },
      );

      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Plan Management (Stripe Products/Prices) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  listPlans: adminProcedure.query(async () => {
    const plans = await stripe.products.list({ active: true, expand: ['data.default_price'] });
    return plans.data.map((product) => ({
      id: product.id,
      name: product.name,
      description: product.description ?? null,
      metadata: product.metadata,
      defaultPrice: product.default_price as Stripe.Price | null,
      createdAt: product.created,
    }));
  }),

  getPlan: adminProcedure
    .input(z.object({ productId: z.string() }))
    .query(async ({ input }) => {
      const product = await stripe.products.retrieve(input.productId, {
        expand: ['default_price'],
      });
      const prices = await stripe.prices.list({
        product: input.productId,
        active: true,
      });
      return {
        id: product.id,
        name: product.name,
        description: product.description ?? null,
        metadata: product.metadata,
        defaultPrice: product.default_price as Stripe.Price | null,
        prices: prices.data.map((p) => ({
          id: p.id,
          unitAmount: p.unit_amount,
          currency: p.currency,
          interval: p.recurring?.interval ?? null,
          intervalCount: p.recurring?.interval_count ?? null,
          metadata: p.metadata,
        })),
        createdAt: product.created,
      };
    }),

  createPlan: adminProcedure
    .input(z.object({
      name: z.string().min(1),
      description: z.string().optional(),
      price: z.number().positive(), // in cents
      currency: z.string().default('usd'),
      interval: z.enum(['month', 'year']).default('month'),
      storageGb: z.number().positive(),
      features: z.array(z.string()).optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const product = await stripe.products.create({
        name: input.name,
        description: input.description,
        metadata: {
          storage_gb: String(input.storageGb),
          features: JSON.stringify(input.features ?? []),
        },
      });

      const price = await stripe.prices.create({
        product: product.id,
        unit_amount: input.price,
        currency: input.currency,
        recurring: {
          interval: input.interval,
        },
        metadata: {
          storage_gb: String(input.storageGb),
        },
      });

      await stripe.products.update(product.id, {
        default_price: price.id,
      });

      await logAuditEvent(
        Number(ctx.session.user.id),
        'admin.plan_created',
        'plan',
        undefined,
        { productId: product.id, name: input.name },
      );

      return { productId: product.id, priceId: price.id };
    }),

  updatePlan: adminProcedure
    .input(z.object({
      productId: z.string(),
      name: z.string().optional(),
      description: z.string().optional(),
      storageGb: z.number().optional(),
      active: z.boolean().optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const updateData: Stripe.ProductUpdateParams = {};
      if (input.name) updateData.name = input.name;
      if (input.description !== undefined) updateData.description = input.description;
      if (input.storageGb !== undefined) {
        updateData.metadata = { storage_gb: String(input.storageGb) };
      }
      if (input.active !== undefined) updateData.active = input.active;

      await stripe.products.update(input.productId, updateData);

      await logAuditEvent(
        Number(ctx.session.user.id),
        'admin.plan_updated',
        'plan',
        undefined,
        { productId: input.productId },
      );

      return { success: true };
    }),

  deletePlan: adminProcedure
    .input(z.object({ productId: z.string() }))
    .mutation(async ({ ctx, input }) => {
      // Archive instead of delete (Stripe best practice)
      await stripe.products.update(input.productId, { active: false });

      await logAuditEvent(
        Number(ctx.session.user.id),
        'admin.plan_deleted',
        'plan',
        undefined,
        { productId: input.productId },
      );

      return { success: true };
    }),

  getPlanSubscribers: adminProcedure
    .input(z.object({ productId: z.string() }))
    .query(async ({ input }) => {
      // Get all prices for this product, then count active subscriptions
      const prices = await stripe.prices.list({
        product: input.productId,
        active: true,
      });
      const priceIds = prices.data.map((p) => p.id);

      let totalSubscribers = 0;
      for (const priceId of priceIds) {
        const subs = await stripe.subscriptions.list({
          price: priceId,
          status: 'active',
          limit: 100,
        });
        totalSubscribers += subs.data.length;
      }

      return { totalSubscribers };
    }),
});

// src/server/trpc/routers/billing.ts
import { router } from '../index';
import { protectedProcedure, publicProcedure } from '../procedures';
import { z } from 'zod';
import { TRPCError } from '@trpc/server';
import {
  stripe,
  getActivePlans,
  getCustomerInvoices,
  getCustomerPaymentMethods,
  createCheckoutSession,
  createPortalSession,
  deletePaymentMethod,
  getOrCreateCustomer,
} from '@/lib/stripe';
import { db } from '@/server/db';
import { logAuditEvent } from '@/server/auth/audit';

export const billingRouter = router({
  // ÔöÇÔöÇÔöÇ Plans ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getPlans: publicProcedure.query(async () => {
    return getActivePlans();
  }),

  // ÔöÇÔöÇÔöÇ Subscription ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getSubscription: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const subscription = await db.subscription.findFirst({
      where: { userId, stripeStatus: { not: 'canceled' } },
      orderBy: { createdAt: 'desc' },
    });
    return subscription;
  }),

  // ÔöÇÔöÇÔöÇ Checkout ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  checkout: protectedProcedure
    .input(z.object({ priceId: z.string(), planName: z.string().optional() }))
    .mutation(async ({ ctx, input }) => {
      const userId = Number(ctx.session.user.id);
      const user = await db.user.findUnique({ where: { id: userId } });
      if (!user) throw new TRPCError({ code: 'NOT_FOUND', message: 'User not found' });

      const session = await createCheckoutSession(
        user.stripeId || '',
        input.priceId,
        `${process.env.NEXT_PUBLIC_APP_URL}/billing`,
        `${process.env.NEXT_PUBLIC_APP_URL}/billing`
      );
      return { url: session.url };
    }),

  // ÔöÇÔöÇÔöÇ Portal ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  portal: protectedProcedure.mutation(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user || !user.stripeId) throw new TRPCError({ code: 'NOT_FOUND', message: 'No Stripe customer' });

    const session = await createPortalSession(
      user.stripeId,
      `${process.env.NEXT_PUBLIC_APP_URL}/settings`
    );
    return { url: session.url };
  }),

  // ÔöÇÔöÇÔöÇ Payment Methods ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  addPaymentMethod: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user || !user.stripeId) return [];
    return getCustomerPaymentMethods(user.stripeId);
  }),

  setDefaultPaymentMethod: protectedProcedure
    .input(z.object({ paymentMethodId: z.string() }))
    .mutation(async ({ ctx, input }) => {
      const userId = Number(ctx.session.user.id);
      const user = await db.user.findUnique({ where: { id: userId } });
      if (!user || !user.stripeId) throw new TRPCError({ code: 'NOT_FOUND', message: 'No Stripe customer' });

      await stripe.paymentMethods.attach(input.paymentMethodId, {
        customer: user.stripeId,
      });
      await stripe.customers.update(user.stripeId, {
        invoice_settings: { default_payment_method: input.paymentMethodId },
      });
      return { success: true };
    }),

  deletePaymentMethod: protectedProcedure
    .input(z.object({ paymentMethodId: z.string() }))
    .mutation(async ({ ctx, input }) => {
      await deletePaymentMethod(input.paymentMethodId);
      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Cancel Subscription ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  cancelSubscription: protectedProcedure.mutation(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);

    const subscription = await db.subscription.findFirst({
      where: { userId, stripeStatus: { notIn: ['canceled', 'incomplete_expired'] } },
      orderBy: { createdAt: 'desc' },
    });

    if (!subscription) {
      throw new TRPCError({ code: 'NOT_FOUND', message: 'No active subscription found' });
    }

    // Cancel on Stripe (at period end)
    const updated = await stripe.subscriptions.update(subscription.stripeId, {
      cancel_at_period_end: true,
    });

    // Update local DB
    await db.subscription.update({
      where: { id: subscription.id },
      data: {
        stripeStatus: 'canceled',
        endsAt: new Date((updated as any).current_period_end * 1000),
      },
    });

    await logAuditEvent(userId, 'subscription.cancel', 'subscription', subscription.id);

    return { success: true };
  }),

  // ÔöÇÔöÇÔöÇ Resume Subscription ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  resumeSubscription: protectedProcedure.mutation(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);

    const subscription = await db.subscription.findFirst({
      where: { userId, stripeStatus: 'canceled' },
      orderBy: { createdAt: 'desc' },
    });

    if (!subscription) {
      throw new TRPCError({ code: 'NOT_FOUND', message: 'No canceled subscription found' });
    }

    // Check if subscription hasn't ended yet
    if (subscription.endsAt && new Date(subscription.endsAt) < new Date()) {
      throw new TRPCError({ code: 'BAD_REQUEST', message: 'Subscription has already ended' });
    }

    // Resume on Stripe
    await stripe.subscriptions.update(subscription.stripeId, {
      cancel_at_period_end: false,
    });

    // Update local DB
    await db.subscription.update({
      where: { id: subscription.id },
      data: {
        stripeStatus: 'active',
        endsAt: null,
      },
    });

    await logAuditEvent(userId, 'subscription.resume', 'subscription', subscription.id);

    return { success: true };
  }),

  // ÔöÇÔöÇÔöÇ Setup Intent ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getSetupIntent: protectedProcedure.mutation(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user) throw new TRPCError({ code: 'NOT_FOUND', message: 'User not found' });

    // Ensure Stripe customer exists
    let customerId = user.stripeId;
    if (!customerId) {
      const customer = await getOrCreateCustomer(userId, user.email, user.name);
      customerId = customer.id;
      await db.user.update({ where: { id: userId }, data: { stripeId: customerId } });
    }

    // Create SetupIntent
    const setupIntent = await stripe.setupIntents.create({
      customer: customerId,
      payment_method_types: ['card'],
    });

    return { clientSecret: setupIntent.client_secret };
  }),

  // ÔöÇÔöÇÔöÇ Invoices ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getInvoices: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user || !user.stripeId) return [];
    return getCustomerInvoices(user.stripeId);
  }),

  getUserInvoices: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const invoices = await db.invoice.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
    return invoices;
  }),

  getInvoicePdf: protectedProcedure
    .input(z.object({ token: z.string() }))
    .query(async ({ ctx, input }) => {
      const invoice = await ctx.db.invoice.findFirst({
        where: {
          token: input.token,
          userId: Number(ctx.session.user.id),
        },
      });
      if (!invoice) throw new TRPCError({ code: 'NOT_FOUND', message: 'Invoice not found' });

      const { getPresignedDownloadUrl } = await import('@/lib/s3');
      const url = await getPresignedDownloadUrl(`invoices/${invoice.token}.pdf`, 3600);
      return { url };
    }),

  getInvoiceByToken: publicProcedure
    .input(z.object({ token: z.string() }))
    .query(async ({ ctx, input }) => {
      const invoice = await ctx.db.invoice.findUnique({
        where: { token: input.token },
        include: {
          user: {
            select: { name: true, email: true },
          },
        },
      });

      if (!invoice) throw new TRPCError({ code: 'NOT_FOUND', message: 'Invoice not found' });

      return invoice;
    }),
});

// src/server/trpc/routers/notifications.ts
import { router } from '../index';
import { protectedProcedure } from '../procedures';
import { z } from 'zod';

export const notificationsRouter = router({
  // ÔöÇÔöÇÔöÇ Notifications ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  list: protectedProcedure
    .input(z.object({ unreadOnly: z.boolean().optional() }).optional())
    .query(async ({ ctx, input }) => {
      const userId = Number(ctx.session.user.id);
      const notifications = await ctx.db.notification.findMany({
        where: {
          userId,
          ...(input?.unreadOnly ? { read: false } : {}),
        },
        orderBy: { createdAt: 'desc' },
        take: 50,
      });
      return notifications;
    }),

  unreadCount: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    const count = await ctx.db.notification.count({
      where: { userId, read: false },
    });
    return count;
  }),

  markRead: protectedProcedure
    .input(z.object({ id: z.number() }))
    .mutation(async ({ ctx, input }) => {
      await ctx.db.notification.update({
        where: { id: input.id },
        data: { read: true },
      });
      return { success: true };
    }),

  markAllRead: protectedProcedure.mutation(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);
    await ctx.db.notification.updateMany({
      where: { userId, read: false },
      data: { read: true },
    });
    return { success: true };
  }),

  delete: protectedProcedure
    .input(z.object({ id: z.number() }))
    .mutation(async ({ ctx, input }) => {
      await ctx.db.notification.delete({ where: { id: input.id } });
      return { success: true };
    }),

  // ÔöÇÔöÇÔöÇ Activity Log ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getRecentActivity: protectedProcedure
    .input(z.object({ limit: z.number().optional() }).optional())
    .query(async ({ ctx, input }) => {
      const userId = Number(ctx.session.user.id);
      const activities = await ctx.db.auditLog.findMany({
        where: { userId },
        orderBy: { createdAt: 'desc' },
        take: input?.limit ?? 20,
        select: {
          id: true,
          action: true,
          resource: true,
          resourceId: true,
          createdAt: true,
        },
      });
      return activities;
    }),

  getAllActivity: protectedProcedure
    .input(z.object({ limit: z.number().optional(), offset: z.number().optional() }).optional())
    .query(async ({ ctx, input }) => {
      const activities = await ctx.db.auditLog.findMany({
        orderBy: { createdAt: 'desc' },
        take: input?.limit ?? 50,
        skip: input?.offset ?? 0,
        select: {
          id: true,
          action: true,
          resource: true,
          resourceId: true,
          createdAt: true,
          user: { select: { id: true, name: true, email: true } },
        },
      });
      return activities;
    }),
});

// Helper to create activity logs
export async function logActivity(
  db: any,
  userId: number,
  action: string,
  resource?: string,
  resourceId?: number,
  metadata?: Record<string, unknown>,
) {
  return db.auditLog.create({
    data: { userId, action, resource, resourceId, metadata },
  });
}

// Helper to create notifications
export async function createNotification(
  db: any,
  userId: number,
  title: string,
  message: string,
  type: string = 'info',
  link?: string,
) {
  return db.notification.create({
    data: { userId, title, message, type, link },
  });
}

// src/server/trpc/routers/user.ts
import { router } from '../index';
import { protectedProcedure } from '../procedures';
import { z } from 'zod';
import { TRPCError } from '@trpc/server';

export const userRouter = router({
  // ÔöÇÔöÇÔöÇ Profile ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getProfile: protectedProcedure.query(async ({ ctx }) => {
    const user = await ctx.db.user.findUnique({
      where: { id: Number(ctx.session.user.id) },
      select: {
        id: true,
        name: true,
        email: true,
        avatar: true,
        role: true,
        createdAt: true,
        settings: true,
      },
    });
    if (!user) throw new TRPCError({ code: 'NOT_FOUND', message: 'User not found' });
    return user;
  }),

  updateProfile: protectedProcedure
    .input(z.object({
      name: z.string().min(1).optional(),
      email: z.string().email().optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const user = await ctx.db.user.update({
        where: { id: Number(ctx.session.user.id) },
        data: {
          ...(input.name && { name: input.name }),
          ...(input.email && { email: input.email }),
        },
      });
      return { user };
    }),

  changePassword: protectedProcedure
    .input(z.object({
      currentPassword: z.string().min(1),
      newPassword: z.string().min(8),
    }))
    .mutation(async ({ ctx, input }) => {
      // Note: Better Auth handles password verification
      // This is a placeholder ÔÇö actual implementation uses Better Auth's changePassword
      return { success: true };
    }),

  uploadAvatar: protectedProcedure
    .input(z.object({ avatarUrl: z.string().url() }))
    .mutation(async ({ ctx, input }) => {
      const user = await ctx.db.user.update({
        where: { id: Number(ctx.session.user.id) },
        data: { avatar: input.avatarUrl },
      });
      return { user };
    }),

  // ÔöÇÔöÇÔöÇ Storage ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  getStorageDetails: protectedProcedure.query(async ({ ctx }) => {
    const userId = Number(ctx.session.user.id);

    const settings = await ctx.db.userSettings.findUnique({
      where: { userId },
    });
    const capacity = settings?.storageCapacity ?? 5;

    const files = await ctx.db.fileManagerFile.findMany({
      where: { userId, deletedAt: null },
      select: { filesize: true, mimetype: true },
    });

    const totalUsed = files.reduce((sum: number, f: { filesize: string | null }) => sum + Number(f.filesize ?? '0'), 0);

    // Breakdown by type
    const breakdown: { images: number; documents: number; videos: number; other: number } = {
      images: 0,
      documents: 0,
      videos: 0,
      other: 0,
    };

    for (const file of files) {
      const mime = file.mimetype ?? '';
      const size = Number(file.filesize ?? '0');
      if (mime.startsWith('image/')) breakdown.images += size;
      else if (mime.startsWith('video/')) breakdown.videos += size;
      else if (
        mime.includes('pdf') ||
        mime.includes('document') ||
        mime.includes('text') ||
        mime.includes('spreadsheet') ||
        mime.includes('presentation')
      ) {
        breakdown.documents += size;
      } else {
        breakdown.other += size;
      }
    }

    return {
      used: totalUsed,
      capacity,
      capacityBytes: capacity * 1024 * 1024 * 1024,
      breakdown,
      fileCount: files.length,
    };
  }),
});

